cd -- "$1" || exit 3; if command -v sha256sum >/dev/null 2>&1; then h=sha256sum; else h='shasum -a 256'; fi; a() { q=.; z=$1; while :; do case $z in */*) q=$q/${z%%/*}; z=${z#*/} ;; *) return 0 ;; esac; if [ -L "$q" ]; then return 1; elif [ -d "$q" ]; then [ -x "$q" ] || return 1; elif [ -e "$q" ]; then return 1; else return 2; fi; done; }; while IFS= read -r p; do a "$p"; v=$?; if [ $v = 2 ]; then printf 'A/%s\n' "$p"; elif [ $v = 1 ] || [ -L "$p" ] || [ -d "$p" ]; then printf 'E/%s\n' "$p"; elif [ -e "$p" ]; then if c=$($h < "$p"); then printf 'H%s/%s\n' "${c%% *}" "$p"; else printf 'E/%s\n' "$p"; fi; else printf 'A/%s\n' "$p"; fi; done